    const verification=`<h3>Session verification samples</h3><div class="epi-table-wrap"><table><thead><tr><th>Employee</th><th>Session</th><th>Login</th><th>Recorded end</th><th>Row duration</th></tr></thead><tbody>${sampleRows||'<tr><td colspan="5">No attributable session rows in this period.</td></tr>'}</tbody></table></div>`;
    return section('attendance','Attendance & Portal Activity','09 · Presence and productive time',`${cards}${table}<h3>Portal-wide attributable activity</h3><div class="epi-score-grid">${bars}</div>${sources}${verification}`);
