  function scores(data){const people=data.reports||[];return section('scores','Role-weighted Scores','10 · Coverage-gated score reconciliation',`<div class="epi-person-grid">${people.map(p=>`<article class="epi-person-card epi-score-headline" style="--person:${color(p)}"><header><i></i><div><strong>${esc(p.name)}</strong><small>${esc(p.role)}</small></div></header><b>${esc(scoreHeadline(p))}</b><span>${esc(p.overall_score?.excluded_sections?.length?`Waiting for: ${p.overall_score.excluded_sections.join(', ')}`:'All core sections measured')}</span></article>`).join('')}</div>${packerScoreAudit(data)}${people.map(p=>`<article class="epi-score-breakdown" style="--person:${color(p)}"><header><strong>${esc(p.name)}</strong><b>${esc(scoreHeadline(p))}</b></header>${Object.entries(p.scored_sections||{}).map(([k,v])=>{const working=v.working||v.supporting?.working||`${v.formula||'Corrected section query'}; n=${num(v.sample)}`;return`<div class="epi-score-row"><span>${esc(k.replaceAll('_',' '))}</span><i><em style="width:${Math.max(0,Math.min(100,Number(v.score)||0))}%"></em></i><b>${v.eligible?pct(v.score):`Not measured · n=${num(v.sample)}`}</b><details class="epi-score-working"><summary>Show the working</summary><p>${esc(working)}</p></details><p class="epi-score-working-print">${esc(working)}</p></div>`;}).join('')}</article>`).join('')}`); }
  function suggestions(data){ const risks=(data.operational_risks||[]).slice(0,8); return section('suggestions','Management Suggestions','11 · Data-backed next actions',`<div class="epi-suggestions">${risks.map((r,i)=>`<article><b>${String(i+1).padStart(2,'0')}</b><div><strong>${esc(r.section)} · ${esc(r.employee)}</strong><p>${esc(r.message)}</p><small>Source: verified report evidence · Severity: ${esc(r.severity)}</small></div></article>`).join('')||'<article><b>01</b><div><strong>Maintain current controls</strong><p>No measured operational risks were identified for the selected period.</p></div></article>'}</div><label class="performance-observation"><strong>Management observation</strong><textarea rows="4" data-manager-note placeholder="Add a private presentation note"></textarea></label>`); }
  function rewards(data){const people=data.reports||[];return section('rewards','Rewards','11 · Threshold-based qualification review',`<div class="epi-source-callout"><strong>Qualification rule</strong><p>Each employee is compared with the configured default or role-specific threshold. Incomplete section coverage always remains provisional.</p></div><div class="epi-table-wrap performance-chart-table"><table><thead><tr><th>Employee</th><th>Role</th><th>Score</th><th>Threshold</th><th>Verdict</th><th>Gap</th><th>Sections below threshold</th></tr></thead><tbody>${people.map(p=>{const r=p.reward||{},below=r.below_threshold_sections||[];return`<tr><td><i style="background:${color(p)}"></i>${esc(p.name)}</td><td>${esc(p.role)}</td><td>${r.score==null?esc(`Provisional — ${num(r.measured_sections)} of ${num(r.total_sections)} sections measured`):pct(r.score)}</td><td>${pct(r.threshold)}<small>${esc(r.threshold_source==='role_override'?'Role override':'Default setting')}</small></td><td>${esc(r.verdict||'Provisional — pending complete data')}</td><td>${r.gap==null?'—':`${r.gap>=0?'+':''}${num(r.gap)} points`}</td><td>${below.length?below.map(x=>`${esc(x.section.replaceAll('_',' '))} (${pct(x.score)})`).join('<br>'):'—'}</td></tr>`;}).join('')}</tbody></table></div>`);}
  function rewardsV2(data){const people=data.reports||[],measured=people.filter(p=>p.reward?.verdict!=='Provisional — pending complete data'),best=[...measured].sort((a,b)=>Number(b.reward?.score)-Number(a.reward?.score))[0],accurate=[...measured].filter(p=>String(p.role_key).includes('packer')&&Number.isFinite(Number(p.orders?.speed_minutes))&&Number.isFinite(Number(p.packing?.accuracy))).sort((a,b)=>Number(a.orders.speed_minutes)-Number(b.orders.speed_minutes))[0];const highlights=[best&&`Best overall performer: ${best.name} · ${pct(best.reward.score)}`,accurate&&`Fastest accurate packer: ${accurate.name} · ${duration(accurate.orders.speed_minutes)} with ${pct(accurate.packing.accuracy)} accuracy`].filter(Boolean);return section('rewards','Rewards','11 · Monthly performance reward programme',`<div class="epi-source-callout"><strong>Monthly recommendation, owner-approved</strong><p>Bronze 75–84.9% · Silver 85–89.9% · Gold 90–100%. Missing evidence produces a provisional recommendation, never a rejection. The discretionary year-end bonus remains separate and is not calculated here.</p></div><div class="kpi-health-grid">${people.map(p=>{const r=p.reward||{},below=r.below_threshold_sections||[];return`<article class="kpi-health-card reward-tier-${esc(String(r.tier||'provisional').toLowerCase().replaceAll(' ','-'))}"><span>${esc(p.name)} · ${esc(r.tier||'Provisional')}</span><strong>${r.score==null?esc(`Provisional — ${num(r.measured_sections)} of ${num(r.total_sections)} sections measured`):pct(r.score)}</strong><small>${esc(r.verdict||'Provisional — pending complete data')} · ${r.next_tier?`${num(r.gap_to_next_tier)} points to ${esc(r.next_tier)}`:'highest tier'}<br>${esc(r.configured_reward||'Reward to be confirmed by owner')}<br>${esc(r.accuracy_coverage||'')} ${esc(r.weights_status||'')}</small><details><summary>Show the working</summary><p>${esc(r.explanation||'')}</p>${below.map(x=>`<p><strong>${esc(x.section.replaceAll('_',' '))}: ${pct(x.score)}</strong><br>${esc(x.working||'')}</p>`).join('')}<p>Previous month: ${esc(r.previous_month_status||'Not calculated')}</p></details><form data-reward-decision data-employee-id="${num(p.id)}" data-tier="${esc(r.tier||'Provisional')}" data-score="${r.score==null?'':num(r.score)}"><label>Decision<select name="reward_action"><option value="approve">Approve recommendation</option><option value="reject">Reject recommendation</option><option value="adjust_score">Manual score adjustment</option></select></label><label>Chosen reward<input name="chosen_reward" placeholder="Voucher, recognition, sponsorship…"></label><label>Value<input name="reward_value" placeholder="Blank if not yet fixed"></label><label>Adjustment<input name="score_adjustment" type="number" step="0.1" min="-100" max="100"></label><label>Reason<textarea name="reason" required maxlength="1500"></textarea></label><button type="submit">Record owner decision</button><small data-reward-result></small></form></article>`;}).join('')}</div><section class="epi-source-callout"><strong>Monthly highlights</strong>${highlights.length?`<ul>${highlights.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>Highlights are withheld until measured, non-provisional components are available.</p>'}</section><section class="epi-source-callout"><strong>Discretionary year-end bonus</strong><p>Separate from the monthly performance programme. It depends on business finances, is not guaranteed, and this portal does not calculate or project it.</p></section>`);}
