  function enhanceComputedDisplays(data=latest){if(!data)return;const orderSection=q('[data-report-page="orders"]',controls.output),analysis=data.orders_analysis||{},summary=analysis.summary||{};if(orderSection){const statGrid=q('.epi-stat-grid',orderSection);if(statGrid&&!statGrid.querySelector('[data-business-revenue]')){const revenue=document.createElement('article');revenue.dataset.businessRevenue='1';revenue.className='epi-stat-card';revenue.innerHTML=`<span>Business total revenue</span><b>N$${Number(summary.business_total_revenue||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}</b><small>${esc(summary.revenue_basis||'Valid paid orders')}</small>`;statGrid.append(revenue);}const modeTable=[...orderSection.querySelectorAll('table')].find(t=>[...t.querySelectorAll('th')].some(th=>th.textContent.trim()==='Deliveries'));if(modeTable&&!modeTable.querySelector('[data-mode-share]')){const th=document.createElement('th');th.dataset.modeShare='1';th.textContent='% Share';modeTable.tHead.rows[0].append(th);const byName=new Map((analysis.mode_breakdown||[]).map(x=>[x.name,x]));[...modeTable.tBodies[0].rows].forEach(row=>{const td=document.createElement('td'),item=byName.get(row.cells[0]?.textContent.trim());td.dataset.modeShare='1';td.textContent=item&&summary.mode_orders_total?pct(100*Number(item.mode_total||0)/Number(summary.mode_orders_total)):'Not measured';row.append(td);});}const head=analysis.head_to_head||[],combined=head.reduce((n,x)=>n+Number(x.packed||0),0),timed=head.filter(x=>Number.isFinite(Number(x.speed_minutes))&&Number(x.speed_minutes)>0),teamAvg=timed.length?timed.reduce((n,x)=>n+Number(x.speed_minutes),0)/timed.length:null;orderSection.querySelectorAll('.epi-score-breakdown').forEach(cardNode=>{if(cardNode.querySelector('[data-head-percentages]'))return;const name=cardNode.querySelector('header strong')?.textContent.trim(),item=head.find(x=>x.name===name);if(!item)return;const p=document.createElement('p');p.dataset.headPercentages='1';const share=combined?100*Number(item.packed||0)/combined:null,pace=teamAvg&&Number(item.speed_minutes)>0?100*teamAvg/Number(item.speed_minutes):null;p.textContent=`Standard-order share ${pct(share)}. Pace ${pct(pace)} (${duration(item.speed_minutes)}); formula: team average standard-order time ÷ employee average standard-order time × 100.`;cardNode.append(p);});}const websiteSection=q('[data-report-page="website-updates"]',controls.output);if(websiteSection){websiteSection.querySelectorAll('.epi-website-duty-card').forEach(cardNode=>{const name=cardNode.querySelector('header strong')?.textContent.trim(),person=(data.reports||[]).find(p=>p.name===name),cards=[...cardNode.querySelectorAll('.epi-website-kpis > *')];if(!person||cards.length<5)return;const target=cards[4],n=person.website?.on_target_count,total=person.website?.on_target_total;if(n!=null&&total!=null){const value=target.querySelector('b,strong');if(value)value.textContent=`${num(n)} of ${num(total)} · ${pct(person.website?.on_time_percent)}`;}});}}
  function normalizeComputedDisplays(data=latest){if(!data)return;const modeTable=[...controls.output.querySelectorAll('[data-report-page="orders"] table')].find(t=>[...t.querySelectorAll('th')].some(th=>th.textContent.trim()==='% Share'));if(modeTable){const cells=[...modeTable.querySelectorAll('tbody [data-mode-share]')];let used=0;cells.forEach((cell,index)=>{const raw=Number.parseFloat(cell.textContent);if(!Number.isFinite(raw))return;if(index===cells.length-1)cell.textContent=`${Math.max(0,100-used).toFixed(1)}%`;else used+=raw;});}controls.output.querySelectorAll('[data-report-page="website-updates"] .epi-website-duty-card').forEach(cardNode=>{const name=cardNode.querySelector('header strong')?.textContent.trim(),person=(data.reports||[]).find(p=>p.name===name),cards=[...cardNode.querySelectorAll('.epi-website-kpis > *')],target=cards[4],note=target?.querySelector('small');if(note&&person?.website?.target_minutes!=null)note.textContent=`Target ${duration(person.website.target_minutes)}`;});}
