  function render(data){ latest=data; if(controls.employee.options.length===1)(data.employees||[]).forEach(p=>controls.employee.add(new Option(`${p.full_name} · ${p.role_name}`,p.id))); controls.output.innerHTML=`<article class="performance-presentation">${hero(data)}${nav()}<main>${overview(data)}${packing(data)}${website(data)}${orders(data)}${bookkeeping(data)}${courier(data)}${tasks(data)}${errors(data)}${attendance(data)}${scores(data)}${suggestions(data)}</main></article><dialog class="epi-evidence-dialog" data-evidence-dialog><button type="button" data-evidence-close>Close</button><div data-evidence-content></div></dialog>`; const note=q('[data-manager-note]',controls.output); if(note)note.value=localStorage.getItem(`epi-report-observation:${data.period.effective_from}:${data.period.to}`)||''; q('[data-performance-period-caption]').textContent=`Active data period: ${data.period.effective_from} to ${data.period.to}`; q('[data-performance-refreshed]').textContent=`Last refreshed: ${new Date(data.last_refreshed_at).toLocaleString('en-GB')}`; q('[data-performance-quality]').textContent=String(data.data_quality?.status||'unknown').replaceAll('_',' '); }
  async function showEvidence(button){ const dialog=q('[data-evidence-dialog]',controls.output),content=q('[data-evidence-content]',dialog); content.innerHTML='<p>Loading verified source records…</p>'; dialog.showModal(); const p=params();p.set('action','evidence');p.set('evidence_type',button.dataset.performanceEvidence); try{const d=await readJson(await fetch(`reports-performance-reports-data.php?${p}`,{headers:{Accept:'application/json'}})),rows=d.rows||[],headers=rows.length?Object.keys(rows[0]):[];content.innerHTML=`<h2>${esc(d.type)} evidence</h2><p>${num(d.total)} source record(s).</p>${rows.length?`<div class="epi-table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h.replaceAll('_',' '))}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${headers.map(h=>`<td>${esc(r[h]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<p>No matching source records.</p>'}`;}catch(e){content.innerHTML=`<p>${esc(e.message)}</p>`;} }
  function setTab(id){ activeTab=id; q('[data-report-page].is-active',controls.output)?.classList.remove('is-active'); q(`[data-report-page="${id}"]`,controls.output)?.classList.add('is-active'); controls.output.querySelectorAll('[data-report-tab]').forEach(b=>b.classList.toggle('is-active',b.dataset.reportTab===id)); }
  async function load(){
    controls.output.setAttribute('aria-busy','true');
    const query=params();
    const request=async id=>{const started=performance.now();try{const data=await readJson(await fetch(`${sectionEndpoints[id]}?${query}`,{headers:{Accept:'application/json'}}));return{id,data,elapsed:Math.round(performance.now()-started),error:null};}catch(error){return{id,data:null,elapsed:Math.round(performance.now()-started),error:error.message};}};
    const first=await request(activeTab),base=first.data;
    if(base){render(base);const firstReason=first.data?.section_errors?.[first.id]||null;replaceSection(first.id,firstReason?sectionError(first.id,firstReason):sectionRenderers[first.id](first.data));q('[data-performance-error]').hidden=true;setTab(activeTab);controls.output.removeAttribute('aria-busy');const results=[first,...await Promise.all(tabIds.filter(id=>id!==activeTab).map(request))];for(const result of results.slice(1)){const reason=result.error||result.data?.section_errors?.[result.id]||null;replaceSection(result.id,reason?sectionError(result.id,reason):sectionRenderers[result.id](result.data));}latest.section_response_times=Object.fromEntries(results.map(result=>[result.id,result.elapsed]));controls.output.dataset.sectionResponseTimes=JSON.stringify(latest.section_response_times);}
    else{controls.output.innerHTML=`<article class="performance-presentation">${nav()}<main>${sectionError(first.id,first.error)}</main></article>`;q('[data-performance-error]').textContent='The selected performance section could not be loaded.';q('[data-performance-error]').hidden=false;}
    setTab(activeTab);controls.output.removeAttribute('aria-busy');
  }
